```mermaid
flowchart TB
  %% Circular-style diagram approximated with a central node + 6 surrounding segments

  C(("STAGES OF<br/>ERICKSON<br/>Psychosocial<br/>Development"))

  subgraph RING[ ]
    direction LR

    CEN["CENTINS4<br/><small>Describe the stage here (as in the diagram): focus of self-development, learning, and developing skills.</small>"]
    SUN["SUNNIES<br/><small>Describe the stage here (as in the diagram): concerns about identity, interests, and self-perception.</small>"]
    RIS["RISTON<br/><small>Describe the stage here (as in the diagram): forming commitments, choices, and personal direction.</small>"]
    OVE["OVEROPTIMIZERS<br/><small>Describe the stage here (as in the diagram): optimism vs. doubt; confidence in abilities and outcomes.</small>"]
    SUA["SUAPE<br/><small>Describe the stage here (as in the diagram): adapting, acceptance, and learning through education/experience.</small>"]
    PAN["PANNES<br/><small>Describe the stage here (as in the diagram): completing education/career; reflection, accomplishment, and legacy.</small>"]
  end

  C --- CEN
  C --- SUN
  C --- RIS
  C --- OVE
  C --- SUA
  C --- PAN

  %% Optional ring links to suggest circular flow
  CEN --- SUN --- RIS --- OVE --- SUA --- PAN --- CEN

  %% Styling
  classDef center fill:#f4b183,stroke:#a65b2a,color:#1b1b1b,stroke-width:2px;
