  classDef seg2 fill:#fdeaa6,stroke:#caa24a,color:#1b1b1b;
  classDef seg3 fill:#cfeefc,stroke:#5aa6c9,color:#1b1b1b;
  classDef seg4 fill:#e3c5ff,stroke:#8e6bb3,color:#1b1b1b;
  classDef seg5 fill:#c9f2b5,stroke:#62a84c,color:#1b1b1b;
