  class n1 c1;
  class n2 c2;
  class n3 c3;
  class n4 c4;

  style l1 fill:transparent,stroke:transparent,color:#111;
  style l2 fill:transparent,stroke:transparent,color:#111;
  style l3 fill:transparent,stroke:transparent,color:#111;
  style l4 fill:transparent,stroke:transparent,color:#111;

